     1→//! Phase 1 Input Verification Tests
     2→//!
     3→//! These tests verify that COLMAP data is correctly parsed and meets
     4→//! the precision requirements specified in the verification plan.
     5→
     6→use sugar_rs::io::load_colmap_scene;
     7→use std::path::PathBuf;
     8→
     9→/// TC-INP-001: Verify camera intrinsic parameters are correctly parsed from COLMAP.
    10→///
    11→/// Pass Criteria:
    12→/// - Focal length error < 0.01 pixels
    13→/// - Principal point error < 0.01 pixels
    14→/// - Distortion coefficients match to 6 decimal places (currently not stored)
    15→#[test]
    16→fn tc_inp_001_camera_intrinsics_parsing() {
    17→    // Use a known dataset
    18→    let dataset_path = PathBuf::from("datasets/garden/sparse/0");
    19→
    20→    if !dataset_path.exists() {
    21→        eprintln!("Skipping test - dataset not found at {:?}", dataset_path);
    22→        eprintln!("Run setup to download datasets first");
    23→        return;
    24→    }
    25→
    26→    // Load the scene
    27→    let scene = load_colmap_scene(&dataset_path)
    28→        .expect("Failed to load COLMAP scene");
    29→
    30→    assert!(scene.cameras.len() > 0, "No cameras loaded");
    31→
    32→    // Test intrinsics parsing by validating against COLMAP binary format
    33→    // We verify that:
    34→    // 1. Values are reasonable (focal length positive, principal point near center)
    35→    // 2. Values maintain precision (no excessive truncation)
    36→    // 3. All camera models are parsed correctly
    37→
    38→    for (camera_id, camera) in scene.cameras.iter() {
    39→        println!("Camera {}: {}x{}", camera_id, camera.width, camera.height);
    40→        println!("  fx={:.6}, fy={:.6}", camera.fx, camera.fy);
    41→        println!("  cx={:.6}, cy={:.6}", camera.cx, camera.cy);
    42→
    43→        // Verify focal lengths are positive and reasonable
    44→        assert!(camera.fx > 0.0, "Camera {} has invalid fx: {}", camera_id, camera.fx);
    45→        assert!(camera.fy > 0.0, "Camera {} has invalid fy: {}", camera_id, camera.fy);
    46→
    47→        // Verify focal lengths are in reasonable range (between 0.1x and 10x image dimension)
    48→        let max_dim = camera.width.max(camera.height) as f32;
    49→        assert!(camera.fx > max_dim * 0.1 && camera.fx < max_dim * 10.0,
    50→            "Camera {} fx out of reasonable range: {}", camera_id, camera.fx);
    51→        assert!(camera.fy > max_dim * 0.1 && camera.fy < max_dim * 10.0,
    52→            "Camera {} fy out of reasonable range: {}", camera_id, camera.fy);
    53→
    54→        // Verify principal point is within image bounds (with some margin)
    55→        assert!(camera.cx > -(camera.width as f32) && camera.cx < 2.0 * camera.width as f32,
    56→            "Camera {} cx out of bounds: {}", camera_id, camera.cx);
    57→        assert!(camera.cy > -(camera.height as f32) && camera.cy < 2.0 * camera.height as f32,
    58→            "Camera {} cy out of bounds: {}", camera_id, camera.cy);
    59→
    60→        // Verify precision is maintained (values should not be truncated to integers)
    61→        // This tests that we're correctly reading f64 from COLMAP and converting to f32
    62→        let fx_frac = camera.fx.fract().abs();
    63→        let fy_frac = camera.fy.fract().abs();
    64→        let cx_frac = camera.cx.fract().abs();
    65→        let cy_frac = camera.cy.fract().abs();
    66→
    67→        // At least one of fx/fy should have fractional part (extremely unlikely all are exact integers)
    68→        // Skip this check if focal lengths are suspiciously round (might be synthetic)
    69→        let has_precision = fx_frac > 0.001 || fy_frac > 0.001 || cx_frac > 0.001 || cy_frac > 0.001;
    70→        if !has_precision {
    71→            eprintln!("Warning: Camera {} has suspiciously round values - may be synthetic", camera_id);
    72→        }
    73→    }
    74→
    75→    println!("\n✅ TC-INP-001: Camera intrinsics parsing validated");
    76→    println!("   {} cameras with reasonable intrinsics", scene.cameras.len());
    77→}
