   103→/// TC-INP-002: Verify camera extrinsic parameters (pose) are correctly parsed from COLMAP.
   104→///
   105→/// Pass Criteria:
   106→/// - Rotation error < 0.1 degrees
   107→/// - Translation error < 0.001 units
   108→/// - All rotation matrices satisfy R^T * R = I within 1e-6
   109→#[test]
   110→fn tc_inp_002_camera_extrinsics_parsing() {
   111→    use nalgebra::Matrix3;
   112→
   113→    // Use a known dataset
   114→    let dataset_path = PathBuf::from("datasets/garden/sparse/0");
   115→
   116→    if !dataset_path.exists() {
   117→        eprintln!("Skipping test - dataset not found at {:?}", dataset_path);
   118→        eprintln!("Run setup to download datasets first");
   119→        return;
   120→    }
   121→
   122→    // Load the scene
   123→    let scene = load_colmap_scene(&dataset_path)
   124→        .expect("Failed to load COLMAP scene");
   125→
   126→    assert!(scene.images.len() > 0, "No images loaded");
   127→
   128→    // Test extrinsics parsing by validating:
   129→    // 1. Rotation quaternions are valid (unit quaternions)
   130→    // 2. Rotation matrices are orthonormal (R^T * R = I)
   131→    // 3. Values maintain precision (not truncated)
   132→
   133→    let mut num_valid = 0;
   134→
   135→    for image_info in scene.images.iter() {
   136→        println!("Image {}: {}", image_info.id, image_info.name);
   137→
   138→        // Extract quaternion components
   139→        let quat = image_info.rotation;
   140→        let qw = quat.w;
   141→        let qx = quat.i;
   142→        let qy = quat.j;
   143→        let qz = quat.k;
   144→
   145→        println!("  Quaternion: w={:.6}, x={:.6}, y={:.6}, z={:.6}", qw, qx, qy, qz);
   146→        println!("  Translation: x={:.6}, y={:.6}, z={:.6}",
   147→            image_info.translation.x, image_info.translation.y, image_info.translation.z);
   148→
   149→        // Verify quaternion is normalized (should be unit quaternion)
   150→        let quat_norm = (qw * qw + qx * qx + qy * qy + qz * qz).sqrt();
   151→        assert!((quat_norm - 1.0).abs() < 1e-6,
   152→            "Image {} quaternion not normalized: norm={}", image_info.id, quat_norm);
   153→
   154→        // Convert quaternion to rotation matrix
   155→        let rotation_matrix: Matrix3<f32> = quat.to_rotation_matrix().into_inner();
   156→
   157→        // Verify rotation matrix is orthonormal: R^T * R = I
   158→        let rt_r: Matrix3<f32> = rotation_matrix.transpose() * rotation_matrix;
   159→        let identity: Matrix3<f32> = Matrix3::identity();
   160→
   161→        for i in 0..3 {
   162→            for j in 0..3 {
   163→                let diff = (rt_r[(i, j)] - identity[(i, j)]).abs();
   164→                assert!(diff < 1e-6,
   165→                    "Image {} rotation matrix not orthonormal at ({},{}): R^T*R - I = {}",
   166→                    image_info.id, i, j, diff);
   167→            }
   168→        }
   169→
   170→        // Verify determinant is +1 (proper rotation, not reflection)
   171→        let det = rotation_matrix.determinant();
   172→        assert!((det - 1.0).abs() < 1e-6,
   173→            "Image {} rotation matrix determinant != 1: det={}", image_info.id, det);
   174→
   175→        // Verify precision is maintained (values should have fractional parts)
   176→        // At least some rotation or translation components should not be exact integers
   177→        let has_rotation_precision =
   178→            qx.fract().abs() > 0.001 || qy.fract().abs() > 0.001 ||
   179→            qz.fract().abs() > 0.001 || qw.fract().abs() > 0.001;
   180→        let has_translation_precision =
   181→            image_info.translation.x.fract().abs() > 0.001 ||
   182→            image_info.translation.y.fract().abs() > 0.001 ||
   183→            image_info.translation.z.fract().abs() > 0.001;
   184→
   185→        if !has_rotation_precision && !has_translation_precision {
   186→            eprintln!("Warning: Image {} has suspiciously round pose values - may be synthetic",
   187→                image_info.id);
   188→        }
   189→
   190→        num_valid += 1;
   191→    }
   192→
   193→    println!("\n✅ TC-INP-002: Camera extrinsics parsing validated");
   194→    println!("   {} images with valid camera poses", num_valid);
   195→    println!("   All rotation matrices are orthonormal (R^T * R = I within 1e-6)");
   196→    println!("   All quaternions are properly normalized");
   197→}
