   199→/// TC-INP-003: Verify consistent coordinate system convention (OpenCV/COLMAP vs OpenGL).
   200→///
   201→/// Pass Criteria:
   202→/// - Projected coordinates match analytical solution within 1e-4
   203→/// - Coordinate system documented and verified
   204→///
   205→/// This test verifies that we use a consistent coordinate system throughout the pipeline:
   206→/// - Camera space: +Z forward (into scene), +X right, +Y down (OpenCV/COLMAP convention)
   207→/// - World to camera: p_cam = R * p_world + t
   208→/// - Projection: [u, v] = [fx * x/z + cx, fy * y/z + cy]
   209→#[test]
   210→fn tc_inp_003_coordinate_system_convention() {
   211→    const TOLERANCE: f32 = 1e-4; // Tolerance for floating-point comparisons
   212→    use nalgebra::{Matrix3, Quaternion, UnitQuaternion, Vector3};
   213→    use sugar_rs::core::Camera;
   214→
   215→    println!("\n=== TC-INP-003: Coordinate System Convention Verification ===\n");
   216→
   217→    // Test Case 1: Identity camera, simple point
   218→    // Camera at origin, looking down +Z axis
   219→    {
   220→        let camera = Camera::new(
   221→            100.0,               // fx
   222→            100.0,               // fy
   223→            50.0,                // cx
   224→            50.0,                // cy
   225→            100,                 // width
   226→            100,                 // height
   227→            Matrix3::identity(), // rotation (identity = no rotation)
   228→            Vector3::zeros(),    // translation (at origin)
   229→        );
   230→
   231→        // Point at (1, 2, 5) in world space
   232→        // With identity camera, world = camera space
   233→        // Expected projection: u = 100 * (1/5) + 50 = 70
   234→        //                      v = 100 * (2/5) + 50 = 90
   235→        let point_world = Vector3::new(1.0, 2.0, 5.0);
   236→        let expected_pixel = Vector3::new(70.0, 90.0, 5.0); // [u, v, depth]
   237→
   238→        let pixel = camera.world_to_pixel(&point_world)
   239→            .expect("Point should be in front of camera");
   240→
   241→        println!("Test 1 - Identity camera:");
   242→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   243→        println!("  Expected pixel: ({:.6}, {:.6})", expected_pixel.x, expected_pixel.y);
   244→        println!("  Computed pixel: ({:.6}, {:.6})", pixel.x, pixel.y);
   245→        println!("  Error: ({:.6}, {:.6})",
   246→            (pixel.x - expected_pixel.x).abs(),
   247→            (pixel.y - expected_pixel.y).abs());
   248→
   249→        assert!((pixel.x - expected_pixel.x).abs() < TOLERANCE,
   250→            "X projection error too large: {} vs {}", pixel.x, expected_pixel.x);
   251→        assert!((pixel.y - expected_pixel.y).abs() < TOLERANCE,
   252→            "Y projection error too large: {} vs {}", pixel.y, expected_pixel.y);
   253→
   254→        println!("  ✓ Identity camera projection correct\n");
   255→    }
   256→
   257→    // Test Case 2: Translated camera
   258→    // Camera translated to (10, 0, 0), still looking down +Z
   259→    {
   260→        let camera = Camera::new(
   261→            100.0,
   262→            100.0,
   263→            50.0,
   264→            50.0,
   265→            100,
   266→            100,
   267→            Matrix3::identity(),
   268→            Vector3::new(10.0, 0.0, 0.0), // translation
   269→        );
   270→
   271→        // Point at (11, 2, 5) in world space
   272→        // In camera space: p_cam = I * (11, 2, 5) + (10, 0, 0) = (21, 2, 5)
   273→        // Expected projection: u = 100 * (21/5) + 50 = 470
   274→        //                      v = 100 * (2/5) + 50 = 90
   275→        let point_world = Vector3::new(11.0, 2.0, 5.0);
   276→        let expected_pixel = Vector3::new(470.0, 90.0, 5.0);
   277→
   278→        let pixel = camera.world_to_pixel(&point_world)
   279→            .expect("Point should be in front of camera");
   280→
   281→        println!("Test 2 - Translated camera:");
   282→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   283→        println!("  Expected pixel: ({:.6}, {:.6})", expected_pixel.x, expected_pixel.y);
   284→        println!("  Computed pixel: ({:.6}, {:.6})", pixel.x, pixel.y);
   285→        println!("  Error: ({:.6}, {:.6})",
   286→            (pixel.x - expected_pixel.x).abs(),
   287→            (pixel.y - expected_pixel.y).abs());
   288→
   289→        assert!((pixel.x - expected_pixel.x).abs() < TOLERANCE,
   290→            "X projection error too large: {} vs {}", pixel.x, expected_pixel.x);
   291→        assert!((pixel.y - expected_pixel.y).abs() < TOLERANCE,
   292→            "Y projection error too large: {} vs {}", pixel.y, expected_pixel.y);
   293→
   294→        println!("  ✓ Translated camera projection correct\n");
   295→    }
   296→
   297→    // Test Case 3: Rotated camera (90° rotation around Y-axis)
   298→    // Camera rotated 90° around Y-axis: was looking at +Z, now looking at +X
   299→    {
   300→        // Rotation by 90° around Y-axis (counter-clockwise when looking down -Y)
   301→        // This rotates +Z to +X
   302→        let angle = std::f32::consts::FRAC_PI_2; // 90 degrees
   303→        let axis = Vector3::y_axis();
   304→        let rotation_quat = UnitQuaternion::from_axis_angle(&axis, angle);
   305→        let rotation_matrix = rotation_quat.to_rotation_matrix().into_inner();
   306→
   307→        let camera = Camera::new(
   308→            100.0,
   309→            100.0,
   310→            50.0,
   311→            50.0,
   312→            100,
   313→            100,
   314→            rotation_matrix,
   315→            Vector3::zeros(),
   316→        );
   317→
   318→        // Point at (5, 2, 1) in world space
   319→        // After 90° rotation around Y: (x,y,z) -> (z, y, -x)
   320→        // In camera space: R * (5, 2, 1) = (1, 2, -5)
   321→        // Depth check: z = -5, which is negative (behind camera)
   322→        // So this point should NOT project
   323→
   324→        // Let's use a point that will be in front
   325→        // Point at (5, 2, -1) in world space
   326→        // After rotation: R * (5, 2, -1) = (-1, 2, -5) - still behind
   327→
   328→        // For a point to be in front after Y-rotation by 90°:
   329→        // We need R * p to have positive z
   330→        // R_y(90°) maps (x,y,z) -> (z, y, -x)
   331→        // For positive z in camera: -x > 0, so x < 0 in world
   332→
   333→        let point_world = Vector3::new(-5.0, 2.0, 1.0);
   334→        // After rotation: (-5, 2, 1) -> (1, 2, 5) in camera space
   335→        // Expected projection: u = 100 * (1/5) + 50 = 70
   336→        //                      v = 100 * (2/5) + 50 = 90
   337→        let expected_pixel = Vector3::new(70.0, 90.0, 5.0);
   338→
   339→        let pixel = camera.world_to_pixel(&point_world)
   340→            .expect("Point should be in front of camera");
   341→
   342→        println!("Test 3 - Rotated camera (90° around Y):");
   343→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   344→        println!("  Expected pixel: ({:.6}, {:.6})", expected_pixel.x, expected_pixel.y);
   345→        println!("  Computed pixel: ({:.6}, {:.6})", pixel.x, pixel.y);
   346→        println!("  Error: ({:.6}, {:.6})",
   347→            (pixel.x - expected_pixel.x).abs(),
   348→            (pixel.y - expected_pixel.y).abs());
   349→
   350→        assert!((pixel.x - expected_pixel.x).abs() < TOLERANCE,
   351→            "X projection error too large: {} vs {}", pixel.x, expected_pixel.x);
   352→        assert!((pixel.y - expected_pixel.y).abs() < TOLERANCE,
   353→            "Y projection error too large: {} vs {}", pixel.y, expected_pixel.y);
   354→
   355→        println!("  ✓ Rotated camera projection correct\n");
   356→    }
   357→
   358→    // Test Case 4: General camera pose (combined rotation and translation)
   359→    {
   360→        // 45° rotation around Y-axis
   361→        let angle = std::f32::consts::FRAC_PI_4; // 45 degrees
   362→        let axis = Vector3::y_axis();
   363→        let rotation_quat = UnitQuaternion::from_axis_angle(&axis, angle);
   364→        let rotation_matrix = rotation_quat.to_rotation_matrix().into_inner();
   365→
   366→        let translation = Vector3::new(1.0, 2.0, 3.0);
   367→
   368→        let camera = Camera::new(
   369→            200.0, // fx
   370→            200.0, // fy
   371→            100.0, // cx
   372→            100.0, // cy
   373→            200,
   374→            200,
   375→            rotation_matrix,
   376→            translation,
   377→        );
   378→
   379→        // Point at (5, 3, 8) in world space
   380→        let point_world = Vector3::new(5.0, 3.0, 8.0);
   381→
   382→        // Manually compute expected projection
   383→        // p_cam = R * p_world + t
   384→        let point_camera = rotation_matrix * point_world + translation;
   385→
   386→        // Should have positive z (in front)
   387→        assert!(point_camera.z > 0.0,
   388→            "Test point should be in front of camera, got z={}", point_camera.z);
   389→
   390→        // Expected projection: [u, v] = [fx * x/z + cx, fy * y/z + cy]
   391→        let expected_u = 200.0 * point_camera.x / point_camera.z + 100.0;
   392→        let expected_v = 200.0 * point_camera.y / point_camera.z + 100.0;
   393→        let expected_pixel = Vector3::new(expected_u, expected_v, point_camera.z);
   394→
   395→        let pixel = camera.world_to_pixel(&point_world)
   396→            .expect("Point should be in front of camera");
   397→
   398→        println!("Test 4 - General camera pose:");
   399→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   400→        println!("  Camera point: ({:.6}, {:.6}, {:.6})", point_camera.x, point_camera.y, point_camera.z);
   401→        println!("  Expected pixel: ({:.6}, {:.6})", expected_pixel.x, expected_pixel.y);
   402→        println!("  Computed pixel: ({:.6}, {:.6})", pixel.x, pixel.y);
   403→        println!("  Error: ({:.6}, {:.6})",
   404→            (pixel.x - expected_pixel.x).abs(),
   405→            (pixel.y - expected_pixel.y).abs());
   406→
   407→        assert!((pixel.x - expected_pixel.x).abs() < TOLERANCE,
   408→            "X projection error too large: {} vs {}", pixel.x, expected_pixel.x);
   409→        assert!((pixel.y - expected_pixel.y).abs() < TOLERANCE,
   410→            "Y projection error too large: {} vs {}", pixel.y, expected_pixel.y);
   411→
   412→        println!("  ✓ General camera projection correct\n");
   413→    }
   414→
   415→    // Test Case 5: Verify point behind camera is rejected
   416→    {
   417→        let camera = Camera::new(
   418→            100.0,
   419→            100.0,
   420→            50.0,
   421→            50.0,
   422→            100,
   423→            100,
   424→            Matrix3::identity(),
   425→            Vector3::zeros(),
   426→        );
   427→
   428→        // Point with negative Z (behind camera)
   429→        let point_world = Vector3::new(1.0, 2.0, -5.0);
   430→        let pixel = camera.world_to_pixel(&point_world);
   431→
   432→        println!("Test 5 - Point behind camera:");
   433→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   434→        println!("  Projection result: {:?}", pixel);
   435→
   436→        assert!(pixel.is_none(),
   437→            "Point behind camera should not project");
   438→
   439→        println!("  ✓ Point behind camera correctly rejected\n");
   440→    }
   441→
   442→    println!("✅ TC-INP-003: Coordinate system convention verified");
   443→    println!("   Convention: OpenCV/COLMAP (Z-forward, camera-to-world)");
   444→    println!("   World to camera: p_cam = R * p_world + t");
   445→    println!("   Projection: [u,v] = [fx*x/z + cx, fy*y/z + cy]");
   446→    println!("   All analytical projections match within {}", TOLERANCE);
   447→}
