   449→/// TC-INP-010: Verify 3D points correctly loaded from COLMAP sparse reconstruction.
   450→///
   451→/// Pass Criteria:
   452→/// - Point count matches source file
   453→/// - Point positions within 1e-5 of source values
   454→/// - Visual alignment with input images (manual check)
   455→#[test]
   456→fn tc_inp_010_colmap_point_cloud_loading() {
   457→    use byteorder::{LittleEndian, ReadBytesExt};
   458→    use std::fs::File;
   459→    use std::io::BufReader;
   460→
   461→    // Use a known dataset
   462→    let dataset_path = PathBuf::from("datasets/garden/sparse/0");
   463→
   464→    if !dataset_path.exists() {
   465→        eprintln!("Skipping test - dataset not found at {:?}", dataset_path);
   466→        eprintln!("Run setup to download datasets first");
   467→        return;
   468→    }
   469→
   470→    // Load the scene using our implementation
   471→    let scene = load_colmap_scene(&dataset_path)
   472→        .expect("Failed to load COLMAP scene");
   473→
   474→    println!("Loaded {} 3D points from COLMAP scene", scene.points.len());
   475→
   476→    // Read the points3D.bin file directly for ground truth comparison
   477→    let points_path = dataset_path.join("points3D.bin");
   478→    let file = File::open(&points_path).expect("Failed to open points3D.bin");
   479→    let mut reader = BufReader::new(file);
   480→
   481→    // Read number of points from binary file
