     1→//! Gaussian representation and cloud data structure.
     2→//!
     3→//! A Gaussian is parameterized by:
     4→//! - Position (mean μ)
     5→//! - Scale (log-space: exp(scale) gives actual scale)
     6→//! - Rotation (quaternion)
     7→//! - Opacity (logit-space: sigmoid(opacity) gives actual opacity)
     8→//! - Spherical harmonics coefficients (view-dependent color)
     9→
    10→use nalgebra::{Matrix3, UnitQuaternion, Vector3};
    11→use serde::{Deserialize, Serialize};
    12→
    13→/// A 3D Gaussian primitive.
    14→///
    15→/// Covariance is stored factorized as scale + rotation for numerical stability:
    16→/// Σ = R · S · S^T · R^T where S = diag(exp(scale))
    17→#[derive(Clone, Debug, Serialize, Deserialize)]
    18→pub struct Gaussian {
    19→    /// Position (mean μ)
    20→    pub position: Vector3<f32>,
    21→
    22→    /// Log-space scale (actual scale = exp(scale))
    23→    /// Stored in log-space for unbounded optimization
    24→    pub scale: Vector3<f32>,
    25→
    26→    /// Rotation as unit quaternion
    27→    /// Quaternions are more stable than Euler angles or matrices for optimization
    28→    pub rotation: UnitQuaternion<f32>,
    29→
    30→    /// Opacity in logit-space (actual opacity = sigmoid(opacity))
    31→    /// Logit-space ensures opacity stays in (0, 1) during optimization
    32→    pub opacity: f32,
    33→
    34→    /// Spherical harmonics coefficients for view-dependent color
    35→    /// [RGB × 16 coefficients] for degree-3 SH
    36→    /// Index 0 is DC component (view-independent color)
    37→    pub sh_coeffs: [[f32; 3]; 16],
    38→}
    39→
    40→impl Gaussian {
    41→    /// Create a new Gaussian with given parameters.
    42→    pub fn new(
    43→        position: Vector3<f32>,
    44→        scale: Vector3<f32>,
    45→        rotation: UnitQuaternion<f32>,
    46→        opacity: f32,
    47→        sh_coeffs: [[f32; 3]; 16],
    48→    ) -> Self {
    49→        Self {
    50→            position,
    51→            scale,
    52→            rotation,
    53→            opacity,
    54→            sh_coeffs,
    55→        }
    56→    }
    57→
    58→    /// Compute the 3D covariance matrix Σ = R · S · S^T · R^T
    59→    ///
    60→    /// The covariance is stored factorized for numerical stability:
    61→    /// - Scale in log-space: actual_scale = exp(self.scale)
    62→    /// - Rotation as unit quaternion
    63→    ///
    64→    /// Reconstruction:
    65→    /// 1. R = quaternion_to_matrix(rotation)
    66→    /// 2. S = diag(exp(scale.x), exp(scale.y), exp(scale.z))
    67→    /// 3. Σ = R · S · S^T · R^T
    68→    pub fn covariance_matrix(&self) -> Matrix3<f32> {
    69→        use crate::core::quaternion_to_matrix;
    70→
    71→        // Get rotation matrix from quaternion
    72→        let rotation_matrix = quaternion_to_matrix(&self.rotation);
    73→
    74→        // Get scale matrix S (diagonal)
    75→        // Scale is stored in log-space, so exp() to get actual values
    76→        let sx = self.scale.x.exp();
    77→        let sy = self.scale.y.exp();
    78→        let sz = self.scale.z.exp();
    79→
    80→        // S · S^T for diagonal matrix is just diag(sx², sy², sz²)
    81→        let s_squared = Matrix3::from_diagonal(&nalgebra::Vector3::new(sx * sx, sy * sy, sz * sz));
    82→
    83→        // Σ = R · S · S^T · R^T = R · S² · R^T
    84→        rotation_matrix * s_squared * rotation_matrix.transpose()
    85→    }
    86→
    87→    /// Get the actual opacity value (sigmoid of stored logit value)
    88→    pub fn actual_opacity(&self) -> f32 {
    89→        // TODO: Implement sigmoid
    90→        crate::core::sigmoid(self.opacity)
    91→    }
    92→
    93→    /// Get the actual scale values (exp of stored log values)
    94→    pub fn actual_scale(&self) -> Vector3<f32> {
    95→        Vector3::new(self.scale.x.exp(), self.scale.y.exp(), self.scale.z.exp())
    96→    }
    97→}
    98→
    99→/// A 2D Gaussian after projection to screen space.
   100→///
   101→/// This is the intermediate representation used during rasterization.
   102→#[derive(Clone, Debug)]
   103→pub struct Gaussian2D {
   104→    /// 2D mean position in pixel coordinates
   105→    pub mean: Vector3<f32>, // (x, y, depth) - depth for sorting
   106→
   107→    /// 2D covariance matrix (2×2 symmetric)
   108→    /// Stored as 3 values: [cov_xx, cov_xy, cov_yy]
   109→    pub cov: Vector3<f32>,
   110→
   111→    /// Color at this Gaussian (after SH evaluation)
   112→    pub color: Vector3<f32>,
   113→
   114→    /// Opacity
   115→    pub opacity: f32,
   116→
   117→    /// Index of the original 3D Gaussian (for gradient backprop)
   118→    pub gaussian_idx: usize,
   119→}
   120→
   121→impl Gaussian2D {
   122→    /// Get the inverse covariance matrix for fast evaluation.
   123→    ///
   124→    /// For a 2×2 symmetric matrix:
   125→    /// inv = 1/det * [cov_yy, -cov_xy]
   126→    ///               [-cov_xy, cov_xx]
   127→    pub fn inverse_covariance(&self) -> (f32, f32, f32) {
   128→        let mut cov_xx = self.cov.x;
   129→        let cov_xy = self.cov.y;
   130→        let mut cov_yy = self.cov.z;
   131→
   132→        // det([a b; b c]) = a*c - b*b
   133→        let mut det = cov_xx * cov_yy - cov_xy * cov_xy;
   134→
   135→        // Add a small diagonal term if the covariance is near-singular.
   136→        // This keeps the renderer numerically stable and matches common practice
   137→        // in splatting implementations (tiny blur in degenerate cases).
   138→        if det.abs() < 1e-12 {
   139→            let eps = 1e-6;
   140→            cov_xx += eps;
   141→            cov_yy += eps;
   142→            det = cov_xx * cov_yy - cov_xy * cov_xy;
   143→        }
   144→
   145→        // inv = 1/det * [ c  -b]
   146→        //               [-b   a]
   147→        let inv_det = 1.0 / det;
   148→        let inv_xx = cov_yy * inv_det;
   149→        let inv_xy = -cov_xy * inv_det;
   150→        let inv_yy = cov_xx * inv_det;
   151→
   152→        (inv_xx, inv_xy, inv_yy)
   153→    }
   154→
   155→    /// Evaluate the 2D Gaussian at a given pixel position.
   156→    ///
   157→    /// Returns exp(-0.5 * (p - μ)^T Σ^{-1} (p - μ))
   158→    pub fn evaluate_at(&self, pixel: Vector3<f32>) -> f32 {
   159→        let dx = pixel.x - self.mean.x;
   160→        let dy = pixel.y - self.mean.y;
   161→
   162→        let (inv_xx, inv_xy, inv_yy) = self.inverse_covariance();
   163→
   164→        // For a symmetric 2×2 inverse covariance:
   165→        // q = [dx dy] * [inv_xx inv_xy; inv_xy inv_yy] * [dx; dy]
   166→        //   = inv_xx*dx² + 2*inv_xy*dx*dy + inv_yy*dy²
   167→        let quad_form = inv_xx * dx * dx + 2.0 * inv_xy * dx * dy + inv_yy * dy * dy;
   168→        (-0.5 * quad_form).exp()
   169→    }
   170→}
   171→
   172→/// A collection of Gaussians.
   173→///
   174→/// Currently using Array-of-Structs (AoS) layout for simplicity.
   175→/// Can migrate to Struct-of-Arrays (SoA) later if needed for SIMD/GPU.
   176→#[derive(Clone, Debug, Serialize, Deserialize)]
   177→pub struct GaussianCloud {
   178→    pub gaussians: Vec<Gaussian>,
   179→}
   180→
   181→impl GaussianCloud {
   182→    /// Create a new empty Gaussian cloud.
   183→    pub fn new() -> Self {
   184→        Self {
   185→            gaussians: Vec::new(),
   186→        }
   187→    }
   188→
   189→    /// Create a cloud from a vector of Gaussians.
   190→    pub fn from_gaussians(gaussians: Vec<Gaussian>) -> Self {
   191→        Self { gaussians }
   192→    }
   193→
   194→    /// Number of Gaussians in the cloud.
   195→    pub fn len(&self) -> usize {
   196→        self.gaussians.len()
   197→    }
   198→
   199→    /// Check if the cloud is empty.
   200→    pub fn is_empty(&self) -> bool {
   201→        self.gaussians.is_empty()
   202→    }
   203→
   204→    /// Add a Gaussian to the cloud.
   205→    pub fn push(&mut self, gaussian: Gaussian) {
   206→        self.gaussians.push(gaussian);
   207→    }
   208→
   209→    /// Get a reference to the Gaussians.
   210→    pub fn as_slice(&self) -> &[Gaussian] {
   211→        &self.gaussians
   212→    }
   213→
   214→    /// Get a mutable reference to the Gaussians.
   215→    pub fn as_mut_slice(&mut self) -> &mut [Gaussian] {
   216→        &mut self.gaussians
   217→    }
   218→}
   219→
   220→impl Default for GaussianCloud {
   221→    fn default() -> Self {
   222→        Self::new()
   223→    }
   224→}
