     1→//! Mathematical utilities (quaternions, activation functions, etc.).
     2→
     3→use nalgebra::{Matrix3, UnitQuaternion};
     4→
     5→/// Convert a unit quaternion to a 3×3 rotation matrix.
     6→///
     7→/// Formula (from quaternion q = w + xi + yj + zk):
     8→/// R = | 1-2(y²+z²)   2(xy-wz)    2(xz+wy)  |
     9→///     | 2(xy+wz)     1-2(x²+z²)  2(yz-wx)  |
    10→///     | 2(xz-wy)     2(yz+wx)    1-2(x²+y²)|
    11→pub fn quaternion_to_matrix(q: &UnitQuaternion<f32>) -> Matrix3<f32> {
    12→    // nalgebra's UnitQuaternion already has to_rotation_matrix()
    13→    // But we implement it explicitly for educational purposes
    14→
    15→    // TODO: Implement for M3
    16→    // For now, use nalgebra's built-in
    17→    q.to_rotation_matrix().into_inner()
    18→}
    19→
    20→/// Sigmoid activation function: σ(x) = 1 / (1 + e^(-x))
    21→///
    22→/// Maps R → (0, 1)
    23→/// Used for opacity (converts unbounded optimization to valid probability)
    24→pub fn sigmoid(x: f32) -> f32 {
    25→    1.0 / (1.0 + (-x).exp())
    26→}
    27→
    28→/// Inverse sigmoid (logit): logit(p) = log(p / (1-p))
    29→///
    30→/// Maps (0, 1) → R
    31→/// Used to convert initial opacity values to optimization space
    32→pub fn inverse_sigmoid(p: f32) -> f32 {
    33→    // Clamp to avoid log(0) or division by zero
    34→    let p_clamped = p.clamp(1e-6, 1.0 - 1e-6);
    35→    (p_clamped / (1.0 - p_clamped)).ln()
    36→}
    37→
    38→/// Compute the Jacobian of perspective projection.
    39→///
    40→/// For a point p_cam = [x, y, z] in camera space,
    41→/// the projected point is [u, v] = [fx*x/z + cx, fy*y/z + cy]
    42→///
    43→/// The Jacobian ∂[u,v]/∂[x,y,z] is:
    44→/// J = | fx/z    0      -fx*x/z² |
    45→///     |  0     fy/z    -fy*y/z² |
    46→///
    47→/// This is critical for projecting 3D covariance to 2D.
    48→pub fn perspective_jacobian(
    49→    point_camera: &nalgebra::Vector3<f32>,
    50→    fx: f32,
    51→    fy: f32,
    52→) -> nalgebra::Matrix2x3<f32> {
    53→    let x = point_camera.x;
    54→    let y = point_camera.y;
    55→    let z = point_camera.z;
    56→
    57→    let z_inv = 1.0 / z;
    58→    let z_inv_sq = z_inv * z_inv;
    59→
    60→    // J = | fx/z    0      -fx*x/z² |
    61→    //     |  0     fy/z    -fy*y/z² |
    62→    nalgebra::Matrix2x3::new(
    63→        fx * z_inv,
    64→        0.0,
    65→        -fx * x * z_inv_sq,
    66→        0.0,
